        | lazymatch goal with |- rw_cells _ _ _ ?cs2 =>
            lazymatch type of OBJ with rw_cells _ _ _ ?cs1 =>
              replace cs2 with cs1; [exact OBJ | unfold wz, b8; list_eq_lia ] end end ].

