Definition vl_post_v (v : bool) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (if v then 1 else 0)) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' LST (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)
    /\ bytes_at usegs m' SP sbs.

Lemma validate_list_post_v : forall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LST SP sbs lrest lo m,
  validate_list_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LST SP sbs lrest lo m
  = vl_post_v (opt_token_list_valid (zbytes sbs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LST SP sbs lrest lo m.
Proof. intros. reflexivity. Qed.

Definition vl_ctx (m m1 : mem) (sp s0v s1v s2v rav : word) (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo : Z)
    (j0 : list byte) (obj : list cell) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -80) [CB 8 j0]
  /\ rw_cells usegs m1 (bv_unsigned sp + -72) obj
  /\ rw_cells usegs m1 (bv_unsigned sp + -32) [C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells usegs m1 LST (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)
  /\ bytes_at usegs m1 SP sbs
  /\ stk usegs m1 lo (bv_unsigned sp + -80)
  /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

Definition vl_pure (sp : word) (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo : Z) : Prop :=
  SP + Z.of_nat (length sbs) < 2^64 /\ lo + VALIDATE_LIST_STACK <= bv_unsigned sp /\ 0xb8000 <= lo
  /\ (bv_unsigned sp <= LST \/ LST + Z.of_nat (cells_size (C8 (wz SP) :: C8 (wz (Z.of_nat (length sbs))) :: lrest)) <= lo)
  /\ (bv_unsigned sp <= SP \/ SP + Z.of_nat (length sbs) <= lo)
  /\ ((0 < length sbs)%nat -> 0 < SP) /\ 0 < LST /\ LST mod 8 = 0.

Local Ltac open_vctx CTX PURE :=
  lazymatch type of CTX with vl_ctx _ _ ?sp _ _ _ _ _ _ _ _ _ _ _ =>
  destruct CTX as (J0 & OBJ & FRhi & LSV & WIN & ST & MU & WM & MI);
  destruct PURE as (SP64 & LO & L98 & SEPL & SEPW & WNZ & LNZ & LAL);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (rw_cells_bound _ _ _ _ LSV) as LB; cbn [cells_size csize Nat.add length] in LB, SEPL;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold OptItCells, VALIDATE_LIST_STACK in * end.

