Lemma vl_exit : forall (v : bool) rax a0x a1x ra sp gp tp t0 t1 t2 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 s2x
    (F : bvmap 5 word) fc (m m1 : mem) (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo : Z)
    (it vp vl err : Z) (pad7 j0 : list byte),
  vl_ctx m m1 sp s0v s1v s2v ra LST SP sbs lrest lo j0 (OptItCells LST it vp vl err pad7) -> vl_pure sp LST SP sbs lrest lo ->
  evt usegs (vl_post_v v ra sp gp tp s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LST SP sbs lrest lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 (wz LST) (wz (if v then 1 else 0)) a0x a1x a2 a3 a4 a5 a6 a7
              s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3ff7c) fc None m1 (seg_rom usegs)).
Proof.
  intros until j0. intros CTX PURE. open_vctx CTX PURE. unfold wz.
  (* [comment removed for export] *)
  step. step. step. step. step.
  join_frame OBJ FRhi (bv_unsigned sp + -72). join_frame J0 OBJ (bv_unsigned sp + -80).
  step. release_frame J0 ST (bv_unsigned sp). step.
  finish.
Qed.

Local Ltac call_optit A lst it vp vl err SP pad7 sbs lrest lo :=
  let S := fresh "OS" in
  pose proof optit_incr_spec as S;
  unfold optit_incr_stmt, optit_incr_post, SZ_TOKIT, TOKIT_STACK, P_OPT_TOKEN_LIST_INCR in S;
  callZ (S A lst it vp vl err SP pad7 sbs lrest lo).

Lemma tok_suffix_off : forall SP i sbs, 0 <= SP -> tok_suffix SP (SP + Z.of_nat i) sbs = skipn i (zbytes sbs).
Proof. intros SP i sbs H. unfold tok_suffix. rewrite zbytes_skipn. f_equal. lia. Qed.

