Local Ltac vl_rebuild_ctx m sp :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | J0 : rw_cells _ mx (bv_unsigned sp + -80) [CB 8 ?j0], OBJ : rw_cells _ mx (bv_unsigned sp + -72) ?ob,
    FRhi : rw_cells _ mx (bv_unsigned sp + -32) [C8 ?s2v; C8 ?s1v; C8 ?s0v; C8 ?rav],
    LSV : rw_cells _ mx ?LST (C8 _ :: C8 _ :: ?lrest), WIN : bytes_at _ mx ?SP ?sbs, ST : stk _ mx ?lo _,
    MU : munch _ m mx, WM : wmono _ m mx, MI : mem_inv _ mx |- _ =>
      let CTX := fresh "CTX" in
      assert (CTX : vl_ctx m mx sp s0v s1v s2v rav LST SP sbs lrest lo j0 ob)
        by (split; [exact J0 | split; [exact OBJ | split; [exact FRhi | split; [exact LSV | split; [exact WIN | split; [exact ST | split; [exact MU | split; [exact WM | exact MI]]]]]]]])
  end end.

