Local Ltac vl_call_incr sp LST it vp vl err SP pad7 sbs lrest lo :=
  call_optit (bv_unsigned sp + -72) LST it vp vl err SP pad7 sbs lrest lo;
  [ assumption | assumption | assumption | lia | lia | lia | cbn [cells_size csize Nat.add length]; lia
  | rewrite ?unsigned_lit by lia; assumption | rewrite ?unsigned_lit by lia; lia | lia
  | rewrite ?unsigned_lit by lia; lia | rewrite ?unsigned_lit by lia; lia
  | rewrite ?unsigned_lit by lia; cbn [cells_size csize Nat.add length]; lia
  | assumption | assumption | assumption | assumption | ];
  try match goal with H : rw_cells _ _ LST _, H' : rw_cells _ _ LST _ |- _ => clear H' end;
  try match goal with H : bytes_at _ _ SP _, H' : bytes_at _ _ SP _ |- _ => clear H' end;
  lazymatch goal with H : rw_cells _ _ (bv_unsigned sp + -72) _ |- _ => rename H into OBJ end;
  lazymatch goal with H : rw_cells _ _ LST _ |- _ => try rename H into LSV end;
  lazymatch goal with H : bytes_at _ _ SP _ |- _ => try rename H into WIN end;
  lazymatch goal with H : stk _ _ _ (bv_unsigned sp + -80) |- _ => try rename H into ST end.
