Lemma vl_loop : forall (k i : nat) rax a0x a1x ra sp gp tp t0 t1 t2 a2 a3 a4 a5 a6 a7 s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (LST SP : Z) (sbs : list byte) (lrest : list cell) (lo : Z)
    (vp vl : Z) (pad7 j0 : list byte),
  (length sbs - i <= k)%nat -> (0 < i <= length sbs)%nat ->
  vl_ctx m m1 sp s0v s1v s2v ra LST SP sbs lrest lo j0 (OptItCells LST (SP + Z.of_nat i) vp vl 0 pad7) -> vl_pure sp LST SP sbs lrest lo ->
  evt usegs (vl_post_v (opt_valid_from (S (length sbs - i)) true (skipn i (zbytes sbs)))
               ra sp gp tp s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LST SP sbs lrest lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2 (wz LST) (wz 1) a0x a1x a2 a3 a4 a5 a6 a7
              (wz 2) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3ffb0) fc None m1 (seg_rom usegs)).
